CREATE TABLE raster_document(id INTEGER PRIMARY KEY, schema TEXT NOT NULL, artifact_id TEXT NOT NULL, title TEXT);
CREATE TABLE raster_scalar64(id INTEGER PRIMARY KEY, value REAL, bits INTEGER NOT NULL, class TEXT NOT NULL);
CREATE TABLE raster_scalar32(id INTEGER PRIMARY KEY, value REAL, bits INTEGER NOT NULL, class TEXT NOT NULL);
CREATE TABLE raster_asset(id INTEGER PRIMARY KEY, document INTEGER NOT NULL REFERENCES raster_document(id), ordinal INTEGER NOT NULL, key TEXT NOT NULL, child_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL, artifact_id TEXT NOT NULL);
CREATE TABLE raster_layer(id INTEGER PRIMARY KEY, document INTEGER REFERENCES raster_document(id), parent INTEGER REFERENCES raster_layer(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL, layer_id TEXT NOT NULL, name TEXT NOT NULL, visible INTEGER NOT NULL, locked INTEGER NOT NULL, opacity INTEGER NOT NULL REFERENCES raster_scalar32(id), blend_mode TEXT NOT NULL);
CREATE TABLE raster_transform(id INTEGER PRIMARY KEY REFERENCES raster_layer(id), x INTEGER NOT NULL REFERENCES raster_scalar64(id), y INTEGER NOT NULL REFERENCES raster_scalar64(id), a INTEGER NOT NULL REFERENCES raster_scalar64(id), b INTEGER NOT NULL REFERENCES raster_scalar64(id), c INTEGER NOT NULL REFERENCES raster_scalar64(id), d INTEGER NOT NULL REFERENCES raster_scalar64(id));
CREATE TABLE raster_mask(id INTEGER PRIMARY KEY REFERENCES raster_layer(id), enabled INTEGER NOT NULL, linked INTEGER NOT NULL, invert INTEGER NOT NULL, width INTEGER, height INTEGER, image_key TEXT);
CREATE TABLE raster_mask_transform(id INTEGER PRIMARY KEY REFERENCES raster_mask(id), x INTEGER NOT NULL REFERENCES raster_scalar64(id), y INTEGER NOT NULL REFERENCES raster_scalar64(id), a INTEGER NOT NULL REFERENCES raster_scalar64(id), b INTEGER NOT NULL REFERENCES raster_scalar64(id), c INTEGER NOT NULL REFERENCES raster_scalar64(id), d INTEGER NOT NULL REFERENCES raster_scalar64(id));
CREATE TABLE raster_pixel(id INTEGER PRIMARY KEY REFERENCES raster_layer(id), width INTEGER, height INTEGER, image_key TEXT);
CREATE TABLE raster_group(id INTEGER PRIMARY KEY REFERENCES raster_layer(id));
CREATE TABLE raster_adjustment(id INTEGER PRIMARY KEY REFERENCES raster_layer(id), adjustment_kind TEXT NOT NULL);
CREATE TABLE raster_parameter(id INTEGER PRIMARY KEY, adjustment INTEGER NOT NULL REFERENCES raster_adjustment(id), ordinal INTEGER NOT NULL, key TEXT NOT NULL, root INTEGER NOT NULL REFERENCES raster_value(id));
CREATE TABLE raster_value(id INTEGER PRIMARY KEY, kind TEXT NOT NULL);
CREATE TABLE raster_boolean(id INTEGER PRIMARY KEY REFERENCES raster_value(id), value INTEGER NOT NULL);
CREATE TABLE raster_signed(id INTEGER PRIMARY KEY REFERENCES raster_value(id), value INTEGER NOT NULL);
CREATE TABLE raster_unsigned(id INTEGER PRIMARY KEY REFERENCES raster_value(id), high INTEGER NOT NULL, low INTEGER NOT NULL);
CREATE TABLE raster_float(id INTEGER PRIMARY KEY REFERENCES raster_value(id), scalar INTEGER NOT NULL REFERENCES raster_scalar64(id));
CREATE TABLE raster_text(id INTEGER PRIMARY KEY REFERENCES raster_value(id), value TEXT NOT NULL);
CREATE TABLE raster_bytes(id INTEGER PRIMARY KEY REFERENCES raster_value(id), value BLOB NOT NULL);
CREATE TABLE raster_array(id INTEGER PRIMARY KEY REFERENCES raster_value(id));
CREATE TABLE raster_item(id INTEGER PRIMARY KEY, array INTEGER NOT NULL REFERENCES raster_array(id), ordinal INTEGER NOT NULL, value INTEGER NOT NULL REFERENCES raster_value(id));
CREATE TABLE raster_object(id INTEGER PRIMARY KEY REFERENCES raster_value(id));
CREATE TABLE raster_member(id INTEGER PRIMARY KEY, object INTEGER NOT NULL REFERENCES raster_object(id), ordinal INTEGER NOT NULL, key TEXT NOT NULL, value INTEGER NOT NULL REFERENCES raster_value(id));
